\item{vcov.}{Optionally either a coefficient covariance matrix or a function to compute such a covariance
matrix from fitted \code{ivreg} model objects. If \code{NULL} (the default) the standard covariance matrix
(based on the information matrix) is used. Alternatively, covariance matrices (e.g., clustered and/or
heteroscedasticity-consistent) can be plugged in to adjust Wald tests or confidence intervals etc.
In \code{summary}, if \code{diagnostics = TRUE}, \code{vcov.} must be a function (not a matrix) because
the alternative covariances are also needed for certain auxiliary models in the diagnostic tests.
If \code{vcov.} is a function, the \code{...} argument can be used to pass on further arguments to
this function.}

\item{df}{For \code{summary}, optional residual degrees of freedom to use in computing model summary.}

\item{...}{arguments to pass down.}

\item{diagnostics}{Report 2SLS "diagnostic" tests in model summary (default is \code{TRUE}). 
These tests are not to be confused with the \emph{regression diagnostics} provided elsewhere in the \pkg{ivreg}
package: see \code{\link{ivregDiagnostics}}.}

\description{
Summary method, including Wald tests and (by default) certain diagnostic tests, for
\code{"ivreg"} model objects, as well as other related inference functions.

\arguments{
\item{x}{regressor matrix.}

\item{y}{vector for the response variable.}

\item{z}{instruments matrix.}

\item{weights}{an optional vector of weights to be used in the fitting
process.}

\item{offset}{an optional offset that can be used to specify an a priori
known component to be included during fitting.}

\item{method}{the method used to fit the stage 1 and 2 regression: 
\code{"OLS"} for traditional 2SLS regression (the default), 
\code{"M"} for M-estimation, or \code{"MM"} for MM-estimation, with the
latter two robust-regression methods implemented via the \code{\link[MASS]{rlm}} 
function in the \pkg{MASS} package.}

\item{rlm.args}{a list of optional arguments to be passed to the \code{\link[MASS]{rlm}} 
function in the \pkg{MASS} package if robust regression is used for the stage 1 and 2 regressions.}

\item{\dots}{further arguments passed to \code{\link[stats:lmfit]{lm.fit}}
or \code{\link[stats:lmfit]{lm.wfit}}, respectively.}

\value{
\code{ivreg.fit} returns an unclassed list with the following
components: 
\item{coefficients}{parameter estimates, from the stage-2 regression.} 
\item{residuals}{vector of model residuals.} 
\item{residuals1}{matrix of residuals from the stage-1 regression.}
\item{residuals2}{vector of residuals from the stage-2 regression.}
\item{fitted.values}{vector of predicted means for the response.}
\item{weights}{either the vector of weights used (if any) or \code{NULL} (if none).} 
\item{offset}{either the offset used (if any) or \code{NULL} (if none).} 
\item{estfun}{a matrix containing the empirical estimating functions.} 
\item{n}{number of observations.} 
\item{nobs}{number of observations with non-zero weights.} 
\item{p}{number of columns in the model matrix x of regressors.}
\item{q}{number of columns in the instrumental variables model matrix z}
\item{rank}{numeric rank of the model matrix for the stage-2 regression.} 
\item{df.residual}{residual degrees of freedom for fitted model.} 
\item{cov.unscaled}{unscaled covariance matrix for the coefficients.} 
\item{sigma}{residual standard error; when method is \code{"M"} or \code{"MM"}, this
is based on the MAD of the residuals (around 0) --- see \code{\link[stats]{mad}}.}
\item{x}{projection of x matrix onto span of z.}
\item{qr}{QR decomposition for the stage-2 regression.}
\item{qr1}{QR decomposition for the stage-1 regression.}
\item{rank1}{numeric rank of the model matrix for the stage-1 regression.}
\item{coefficients1}{matrix of coefficients from the stage-1 regression.}
\item{df.residual1}{residual degrees of freedom for the stage-1 regression.} 
\item{exogenous}{columns of the \code{"regressors"} matrix that are exogenous.}
\item{endogenous}{columns of the \code{"regressors"} matrix that are endogenous.}
\item{instruments}{columns of the \code{"instruments"} matrix that are
instruments for the endogenous variables.}
\item{method}{the method used for the stage 1 and 2 regressions, one of \code{"OLS"},
\code{"M"}, or \code{"MM"}.}
\item{rweights}{a matrix of robustness weights with columns for each of the stage-1
regressions and for the stage-2 regression (in the last column) if the fitting method is 
\code{"M"} or \code{"MM"}, \code{NULL} if the fitting method is \code{"OLS"}.}
\item{hatvalues}{a matrix of hatvalues. For \code{method = "OLS"}, the matrix consists of two
columns, for each of the stage-1 and stage-2 regression; for \code{method = "M"} or \code{"MM"},
there is one column for \emph{each} stage-1 regression and for the stage-2 regression. }
}
\description{
Fit instrumental-variable regression by two-stage least squares (2SLS). This is
equivalent to direct instrumental-variables estimation when the number of
instruments is equal to the number of predictors. Alternative robust-regression
estimation is also supported, based on M-estimation (2SM) or MM-estimation (2SMM).
}
\details{
\code{\link{ivreg}} is the high-level interface to the work-horse function
\code{ivreg.fit}. \code{ivreg.fit} is essentially a convenience interface to
\code{\link[stats:lmfit]{lm.fit}} (or \code{\link[stats:lmfit]{lm.wfit}})
for first projecting \code{x} onto the image of
\code{z}, then running a regression of \code{y} on the projected
\code{x}, and computing the residual standard deviation.
}

\arguments{
\item{X}{Numeric vector or one dimensional matrix/data frame, the running variable.}

\item{c}{Numeric, specifies the threshold or cutoff value in the support of \code{X},
which determines the two samples (e.g., control and treatment units in RD settings).
Default is \code{0}.}

\item{p}{Nonnegative integer, specifies the local polynomial order used to construct
the density estimators. Default is \code{2} (local quadratic approximation).}

\item{q}{Nonnegative integer, specifies the local polynomial order used to construct
the bias-corrected density estimators. Default is \code{p+1} (local cubic approximation
for default \code{p=2}).}

\item{fitselect}{String, specifies the density estimation method.
\code{"unrestricted"} for density estimation without any restrictions (two-sample,
unrestricted inference). This is the default option.
\code{"restricted"} for density estimation assuming equal distribution function and
higher-order derivatives.}

\item{kernel}{String, specifies the kernel function used to construct the local
polynomial estimators.
\code{"triangular"}: \code{K(u)=(1-|u|)*(|u|<=1)}. This is the
default option.
\code{"epanechnikov"}: \code{K(u) = 0.75*(1-u^2)*(|u|<=1)}.
\code{"uniform"}: \code{K(u) = 0.5 * (|u|<=1)}.}

\item{vce}{String, specifies the procedure used to compute the variance-covariance matrix estimator.
\code{"plugin"} for asymptotic plug-in standard errors.
\code{"jackknife"} for jackknife standard errors. This is the default option.}

\item{massPoints}{\code{TRUE} (default) or \code{FALSE}, specifies whether to adjust for
mass points in the data.}

\item{h}{Numeric, specifies the bandwidth used to construct the density estimators on the two
sides of the cutoff.  If not specified, the bandwidth h is computed by the companion command
\code{\link{rdbwdensity}}  If two bandwidths are specified, the first bandwidth is used
for the data below the cutoff and the second bandwidth is used for the data above the cutoff.}

\item{bwselect}{String, specifies the bandwidth selection procedure to be used.
\code{"each"} based on MSE of each density estimator separately (two distinct bandwidths, \code{hl} and \code{hr}).
\code{"diff"} based on MSE of difference of two density estimators (one common bandwidth, \code{hl=hr}).
\code{"sum"} based on MSE of sum of two density estimators (one common bandwidth, \code{hl=hr}).
\code{"comb"} bandwidth is selected as a combination of the alternatives above. This is the default option.
For \code{fitselect="unrestricted"}, it selects \code{median(each,diff,sum)}. For \code{fitselect = "restricted"},
it selects \code{min(diff,sum)}.}

\item{all}{\code{TRUE} or \code{FALSE} (default), if specified, will report two
testing procedures: conventional test statistic (not valid when using MSE-optimal bandwidth choice)
and robust bias-corrected statistic.}

\item{regularize}{\code{TRUE} (default) or \code{FALSE}, specifies whether to conduct local sample size checking.
When set to \code{TRUE}, the bandwidth is chosen such that the local region includes
at least \code{nLocalMin} observations and at least \code{nUniqueMin} unique observations.}

\item{nLocalMin}{Nonnegative integer, specifies the minimum number of observations in each local neighborhood.
This option will be ignored if set to \code{0}, or if \code{regularize=FALSE} is used. Default is \code{20+p+1}.}

\item{nUniqueMin}{Nonnegative integer, specifies the minimum number of unique observations in
each local neighborhood. This option will be ignored if set to \code{0}, or if \code{regularize=FALSE} is used.
Default is \code{20+p+1}.}

\item{bino}{\code{TRUE} (default) or \code{FALSE}, specifies whether to conduct binomial tests. By default,
the initial (smallest) window contains at least 20 observations on each side, and its length is also used as the increment
for subsequent windows. This feature is based on the \code{\link{binom.test}} function.}

\value{
\item{hat}{\code{left}/\code{right}: density estimate to the left/right of cutoff; \code{diff}: difference in
  estimated densities on the two sides of cutoff.}
\item{sd_asy}{\code{left}/\code{right}: standard error for the estimated density to the left/right of the
  cutoff; \code{diff}: standard error for the difference in estimated densities. (Based on
  asymptotic formula.)}
\item{sd_jk}{\code{left}/\code{right}: standard error for the estimated density to the left/right of the
  cutoff; \code{diff}: standard error for the difference in estimated densities. (Based on the
  jackknife method.)}
\item{test}{\code{t_asy}/\code{t_jk}: t-statistic for the density discontinuity test, with standard error
  based on asymptotic formula or the jackknife; \code{p_asy}/\code{p_jk}: p-value for the density
  discontinuity test, with standard error based on asymptotic formula or the jackknife.}
\item{hat_p}{Same as \code{hat}, without bias correction (only available when \code{all=TRUE}).}
\item{sd_asy_p}{Same as \code{sd_asy}, without bias correction (only available when \code{all=TRUE}).}
\item{sd_jk_p}{Same as \code{sd_jk}, without bias correction (only available when \code{all=TRUE}).}
\item{test_p}{Same as \code{test}, without bias correction (only available when \code{all=TRUE}).}
\item{N}{\code{full}: full sample size; \code{left}/\code{right}: sample size to the left/right of the cutoff;
  \code{eff_left}/\code{eff_right}: effective sample size to the left/right of the cutoff (this depends
  on the bandwidth).}
\item{h}{\code{left}/\code{right}: bandwidth used to the left/right of the cutoff.}
\item{opt}{Options passed to the function.}
\item{bino}{Binomial test results. \code{leftWindow}/\code{rightWindow}: window lengths.
   \code{leftN}/\code{rightN}: number of observations. \code{pval}: p-values.}
\item{X_min}{\code{left}/\code{right}: the samllest observation to the left/right of the cutoff.}
\item{X_max}{\code{left}/\code{right}: the largest observation to the left/right of the cutoff.}
}
\description{
\code{rddensity} implements manipulation testing procedures using the
  local polynomial density estimators proposed in Cattaneo, Jansson and Ma (2020),
  and implements graphical procedures with valid confidence bands using the results
  in Cattaneo, Jansson and Ma (2022, 2023).  In addition, the command provides complementary
  manipulation testing based on finite sample exact binomial testing following the
  esults in Cattaneo, Frandsen and Titiunik (2015) and Cattaneo, Frandsen and
  Vazquez-Bare (2017). For an introduction to manipulation testing see McCrary (2008).

 A companion \code{Stata} package is described in Cattaneo, Jansson and Ma (2018).

Companion commands: \code{\link{rdbwdensity}} for data-driven bandwidth selection, and
  \code{\link{rdplotdensity}} for density plots.

\arguments{
\item{Y}{a vector containing the values of the outcome variable.}

\item{R}{a vector containing the values of the running variable.}

\item{cutoff}{the RD cutoff (default is 0).}

\item{wl}{the left limit of the window. The default takes the minimum of the running variable.}

\item{wr}{the right limit of the window. The default takes the maximum of the running variable.}

\item{statistic}{the randomization test statistic to be used. Allowed options are \code{diffmeans} (difference in means statistic), \code{ksmirnov} (Kolmogorov-Smirnov statistic), \code{ranksum} (Wilcoxon-Mann-Whitney standardized statistic), and \code{all}. Default option is \code{diffmeans}. The statistic \code{ttest} is equivalent to \code{diffmeans} and included for backward compatibility.}

\item{p}{the order of the polynomial for the outcome adjustment model (default is 0).}

\item{evall}{the point to the left of the cutoff at which the adjusted outcome is evaluated. Default is the cutoff value.}

\item{evalr}{the point to the right of the cutoff at which the adjusted outcome is evaluated. Default is the cutoff value.}

\item{kernel}{specifies the type of kernel to use as a weighting scheme. Allowed kernel types are \code{uniform} (uniform kernel), \code{triangular} (triangular kernel), and \code{epan} (Epanechnikov kernel). Default is \code{uniform}.}

\item{fuzzy}{indicates that the RD design is fuzzy. \code{fuzzy} can be specified as a vector containing the values of the endogenous treatment variable, or as a list where the first element is the vector of endogenous treatment values and the second element is a string containing the statistic to be used. Allowed statistics are \code{ar} or \code{itt} (Anderson-Rubin/intention-to-treat statistic) and \code{tsls} (2SLS statistic). Default statistic is \code{ar}. The \code{tsls} statistic relies on a large-sample approximation.}

\item{nulltau}{the value of the treatment effect under the null hypothesis (default is 0).}

\item{d}{the effect size for asymptotic power calculation. Default is 0.5 times the standard deviation of the outcome variable for the control group.}

\item{dscale}{the fraction of the standard deviation of the outcome variable for the control group used as the alternative hypothesis for asymptotic power calculation. Default is 0.5.}

\item{ci}{calculates a confidence interval for the treatment effect. The first element specifies alpha (typically 0.05 or 0.01); remaining elements specify a treatment-effect grid. TSLS uses normal intervals. Polynomial sharp-design mean contrasts use normal intervals unless a grid is supplied. Other cases invert tests over a grid; polynomial fuzzy Anderson-Rubin requires an explicit grid. At \code{p = 0}, test inversion uses \code{rdsensitivity}. Use a sufficiently wide grid to avoid truncating the confidence set.}

\item{interfci}{the level for Rosenbaum's confidence interval under arbitrary interference between units.}

\item{bernoulli}{the probabilities of treatment for each unit when assignment mechanism is a Bernoulli trial. This option should be specified as a vector of length equal to the length of the outcome and running variables.}

\item{reps}{the number of replications (default is 1000).}

\item{seed}{the seed to be used for the randomization test.}

\item{covariates}{the covariates used by \code{rdwinselect} to choose the window when \code{wl} and \code{wr} are not specified. This should be a matrix of size n x k where n is the total sample size and k is the number of covariates.}

\item{obsmin}{the minimum number of observations above and below the cutoff in the smallest window used by the companion command \code{rdwinselect}. Default is 10.}

\item{wmin}{the smallest window to be used (if \code{obsmin} is not specified) by the companion command \code{rdwinselect}. Specifying both \code{wmin} and \code{obsmin} returns an error.}

\item{wobs}{the number of observations to be added on each side of the cutoff at each step.}

\item{wstep}{the increment in window length (if \code{obsstep} is not specified) by the companion command \code{rdwinselect}. Specifying both \code{obsstep} and \code{wstep} returns an error.}

\item{wasymmetric}{allows for asymmetric windows around the cutoff when \code{wobs} is specified.}

\item{wmasspoints}{specifies that the running variable is discrete and each masspoint should be used as a window.}

\item{nwindows}{the number of windows to be used by the companion command \code{rdwinselect}. Default is 10.}

\item{dropmissing}{drop rows with missing values in covariates when calculating windows.}

\item{rdwstat}{the statistic to be used by the companion command \code{rdwinselect} (see the corresponding help file for options). Default option is \code{diffmeans}.}

\item{approx}{forces the companion command \code{rdwinselect} to conduct the covariate balance tests using a large-sample approximation instead of finite-sample exact randomization inference methods.}

\item{rdwreps}{the number of replications to be used by the companion command \code{rdwinselect}. Default is 1000.}

\item{level}{the minimum accepted value of the p-value from the covariate balance tests to be used by the companion command \code{rdwinselect}. Default is .15.}

\item{plot}{draws a scatter plot of the minimum p-value from the covariate balance test against window length implemented by the companion command \code{rdwinselect}.}

\item{firststage}{reports the results from the first step when using tsls.}

\item{obsstep}{the minimum number of observations to be added on each side of the cutoff for the sequence of fixed-increment nested windows. Default is 2. This option is deprecated and only included for backward compatibility.}

\item{vce}{heteroskedasticity-consistent variance estimator for \code{p > 0}: \code{HC1}, \code{HC2}, or \code{HC3} (default). Ignored when \code{p = 0}.}

\value{
A list containing:
\item{sumstats}{matrix of full-sample and window-specific summary statistics.}
\item{obs.stat}{observed statistic or statistics.}
\item{p.value}{randomization p-value or p-values; \code{NA} when \code{p > 0}.}
\item{asy.pvalue}{asymptotic p-value or p-values.}
\item{window}{chosen window endpoints.}
\item{ci}{confidence interval; included only when \code{ci} is specified.}
\item{interf.ci}{confidence interval under interference; included only when
\code{interfci} is specified.}

\item{p.requested, p}{requested and effective polynomial degrees.}
\item{vce}{HC variance estimator; \code{NA} when \code{p = 0}.}
\item{inference}{inference method used.}
\item{se}{standard error; included when the effective \code{p > 0}.}
}
\description{
\code{rdrandinf} implements randomization inference and related methods for RD designs,
using observations in a specified or data-driven selected window around the cutoff where
local randomization is assumed to hold.
}
\details{
With \code{p > 0}, mean contrasts, fuzzy Anderson-Rubin tests, and fuzzy TSLS/Wald
use large-sample normal inference from the full polynomial regression, with
HC3 standard errors by default; no randomization p-value is computed.
HC3 does not guarantee finite-sample size control; TSLS/Wald also requires a sufficiently strong first stage.
TSLS uses structural residuals and leverage from projected second-stage regressors.
Fuzzy Anderson-Rubin confidence sets require an explicit treatment-effect grid in ci.
For ksmirnov, ranksum, all, or interfci, a positive p is replaced by \code{p = 0}
and a warning is issued at the end. With \code{p = 0}, existing inference methods
and variance defaults are retained; TSLS tests honor \code{nulltau} and the requested CI level.

\item{wlist_right}{right endpoints of the candidate windows.}
\item{results}{matrix containing the minimum covariate-balance p-value,
selected covariate index, binomial-test p-value, sample sizes below and
above the cutoff, and window endpoints for each candidate window.}
\item{summary}{matrix of sample-size summaries by side of the cutoff.}

\item{p.requested, p}{requested and effective polynomial degrees.}
\item{vce}{HC variance estimator; \code{NA} when \code{p = 0}.}
\item{inference}{inference method used.}
}
\description{
\code{rdwinselect} implements a window-selection procedure based on balance
 tests for RD designs under local randomization. Specifically, it constructs a
 sequence of nested windows around the RD cutoff and reports binomial tests for
 the running variable and covariate balance tests for the covariates (if
 specified). The recommended window is the largest window around the cutoff
 such that the minimum p-value from the balance tests is larger than a
 prespecified level for all nested (smaller) windows. By default, the p-values
 are calculated using randomization inference methods.
}
\details{
With \code{p > 0}, mean balance tests use large-sample normal inference from the full
polynomial regression, with HC3 standard errors by default, regardless of approx.
For ksmirnov, ranksum, or hotelling, a positive p is replaced by \code{p = 0}
and a warning is issued at the end. Inference with \code{p = 0} is unchanged.

\title{Local-Polynomial RD Estimation with Robust Confidence Intervals}
\description{

\code{\link{rdrobust}} implements local polynomial Regression Discontinuity (RD) point estimators with robust bias-corrected confidence intervals and inference procedures developed in Calonico, Cattaneo and Titiunik (2014a), Calonico, Cattaneo and Farrell (2018), Calonico, Cattaneo, Farrell and Titiunik (2019), and Calonico, Cattaneo and Farrell (2020). It also computes alternative estimation and inference procedures available in the literature. 

Companion commands are: \code{\link{rdbwselect}} for data-driven bandwidth selection, and \code{\link{rdplot}} for data-driven RD plots (see Calonico, Cattaneo and Titiunik (2015a) for details).

A detailed introduction to this command is given in Calonico, Cattaneo and Titiunik (2015b), and Calonico, Cattaneo, Farrell and Titiunik (2017). A companion \code{Stata} package is described in Calonico, Cattaneo and Titiunik (2014b).

For more details, and related Stata and R packages useful for analysis of RD designs, visit \url{https://rdpackages.github.io/}

\usage{rdrobust(y, x, c = NULL,  fuzzy = NULL, 
          deriv = NULL, p = NULL, q = NULL, 
          h = NULL, b = NULL, rho = NULL, 
          covs = NULL,  covs_drop = TRUE, ginv.tol = 1e-20,
          kernel = "tri", weights = NULL, bwselect = "mserd", 
          vce = "nn", cluster = NULL, 
          nnmatch = 3, level = 95, scalepar = 1, scaleregul = 1, 
          sharpbw = FALSE, subset = NULL,
          masspoints = "adjust", bwcheck = NULL,
          bwrestrict = TRUE, stdvars = FALSE, data = NULL)}
\arguments{
  \item{y}{is the dependent variable.}
  \item{x}{is the running variable (a.k.a. score or forcing variable).}
  \item{c}{specifies the RD cutoff in \code{x}; default is \code{c = 0}.}
  \item{fuzzy}{specifies the treatment status variable used to implement fuzzy RD estimation (or Fuzzy Kink RD if \code{deriv=1} is also specified). Default is Sharp RD design and hence this option is not used.} 
  \item{deriv}{specifies the order of the derivative of the regression functions to be estimated. Default is \code{deriv=0} (for Sharp RD, or for Fuzzy RD if \code{fuzzy} is also specified). Setting \code{deriv=1} results in estimation of a Kink RD design (up to scale), or Fuzzy Kink RD if \code{fuzzy} is also specified.}
  \item{p}{specifies the order of the local-polynomial used to construct the point-estimator; default is \code{p = 1} (local linear regression).}
  \item{q}{specifies the order of the local-polynomial used to construct the bias-correction; default is \code{q = 2} (local quadratic regression).}
  \item{h}{specifies the main bandwidth used to construct the RD point estimator. If not specified, bandwidth \code{h} is computed by the companion command \code{\link{rdbwselect}}. If two bandwidths are specified, the first bandwidth is used for the data below the cutoff and the second bandwidth is used for the data above the cutoff.}
  \item{b}{specifies the bias bandwidth used to construct the bias-correction estimator. If not specified, bandwidth \code{b} is computed by the companion command \code{\link{rdbwselect}}. If two bandwidths are specified, the first bandwidth is used for the data below the cutoff and the second bandwidth is used for the data above the cutoff.}
  \item{rho}{specifies the value of \code{rho}, so that the bias bandwidth \code{b} equals \code{h/rho}. Default is \code{rho = 1} if \code{h} is specified but \code{b} is not.}
  \item{covs}{additional covariates to be used for efficiency improvements. One of:
  \itemize{
    \item a one-sided \code{\link{formula}}, e.g. \code{~ z1 + z2 + factor(g) + I(z3^2)}: processed with \code{\link{model.matrix}}, so factors are expanded to contrasts, interactions are supported, and transformations such as \code{I(\dots)}, \code{log()}, and \code{poly()} work. The intercept column is dropped automatically. Symbols are looked up in \code{data} first (if supplied), then in the caller's environment;
    \item a character vector of column names (requires \code{data =}), e.g. \code{c("z1", "z2")}: selected as \code{data[, covs]} and coerced to a matrix. Useful for programmatic specifications;
    \item a numeric vector, matrix, or data frame: passed through unchanged (backwards compatible).
  }}
  \item{covs_drop}{if TRUE, it checks for collinear additional covariates and drops them. Default is TRUE.}
  \item{ginv.tol}{tolerance used to invert matrices involving covariates when \code{covs_drop=TRUE}.}
  \item{kernel}{is the kernel function used to construct the local-polynomial estimator(s). Options are \code{triangular} (default option), \code{epanechnikov} and \code{uniform}.}
  \item{weights}{is the variable used for optional weighting of the estimation procedure. The unit-specific weights multiply the kernel function.}

\item{bwselect}{specifies the bandwidth selection procedure to be used. By default it computes both \code{h} and \code{b}, unless \code{rho} is specified, in which case it only computes \code{h} and sets \code{b=h/rho}.}
Options are:

\code{mserd} one common MSE-optimal bandwidth selector for the RD treatment effect estimator.

\code{msetwo} two different MSE-optimal bandwidth selectors (below and above the cutoff) for the RD treatment effect estimator.

\code{msesum} one common MSE-optimal bandwidth selector for the sum of regression estimates (as opposed to difference thereof).

\code{msecomb1} for min(\code{mserd},\code{msesum}).

\code{msecomb2} for median(\code{msetwo},\code{mserd},\code{msesum}), for each side of the cutoff separately.

\code{cerrd} one common CER-optimal bandwidth selector for the RD treatment effect estimator.

\code{certwo} two different CER-optimal bandwidth selectors (below and above the cutoff) for the RD treatment effect estimator.

\code{cersum} one common CER-optimal bandwidth selector for the sum of regression estimates (as opposed to difference thereof).

\code{cercomb1} for min(\code{cerrd},\code{cersum}).

\code{cercomb2} for median(\code{certwo},\code{cerrd},\code{cersum}), for each side of the cutoff separately.

Note: MSE = Mean Square Error; CER = Coverage Error Rate.
Default is \code{bwselect=mserd}. For details on implementation see Calonico, Cattaneo and Titiunik (2014a), Calonico, Cattaneo and Farrell (2018), and Calonico, Cattaneo, Farrell and Titiunik (2019), and the companion software articles.

\item{vce}{specifies the procedure used to compute the variance-covariance matrix estimator.
Options are:

\code{nn} for heteroskedasticity-robust nearest neighbor variance estimator with \code{nnmatch} the (minimum) number of neighbors to be used.

\code{hc0} for heteroskedasticity-robust plug-in residuals variance estimator without weights.

\code{hc1} for heteroskedasticity-robust plug-in residuals variance estimator with \code{hc1} weights.

\code{hc2} for heteroskedasticity-robust plug-in residuals variance estimator with \code{hc2} weights.

\code{hc3} for heteroskedasticity-robust plug-in residuals variance estimator with \code{hc3} weights.

\code{cr1} for CR1 cluster-robust variance estimator with degrees-of-freedom correction at the cluster level. Requires \code{cluster} to be specified.

\code{cr2} for CR2 cluster-robust variance estimator with leverage adjustments (Bell-McCaffrey). Requires \code{cluster} to be specified.

\code{cr3} for CR3 cluster-robust variance estimator with leave-one-cluster-out jackknife (Pustejovsky-Tipton); most conservative. Requires \code{cluster} to be specified.

Default is \code{vce=nn}. When \code{cluster} is specified, only \code{vce=cr1}, \code{vce=cr2}, and \code{vce=cr3} are valid; other options are automatically mapped to the corresponding cluster variant with a warning.

The CR2/CR3 leverage correction applies to both the conventional and the robust bias-corrected standard errors, including when the point-estimation bandwidth \code{h} differs from the bias-correction bandwidth \code{b}; in that case the cluster leverage is computed from the bias (\code{b}) regression.}
  \item{cluster}{indicates the cluster ID variable used for cluster-robust variance estimation. Must be combined with \code{vce=cr1}, \code{vce=cr2}, or \code{vce=cr3}.}
  \item{nnmatch}{to be combined with for \code{vce=nn} for heteroskedasticity-robust nearest neighbor variance estimator with \code{nnmatch} indicating the minimum number of neighbors to be used. Default is \code{nnmatch=3}}
  \item{level}{sets the confidence level for confidence intervals; default is \code{level = 95}.}
  \item{scalepar}{specifies scaling factor for RD parameter of interest. This option is useful when the population parameter of interest involves a known multiplicative factor (e.g., sharp kink RD).  Default is \code{scalepar = 1} (no scaling).}
  \item{scaleregul}{specifies scaling factor for the regularization term added to the denominator of the bandwidth selectors. Setting \code{scaleregul = 0} removes the regularization term from the bandwidth selectors; default is \code{scaleregul = 1}.}
  \item{sharpbw}{option to perform fuzzy RD estimation using a bandwidth selection procedure for the sharp RD model. This option is automatically selected if there is perfect compliance at either side of the cutoff.}
  \item{subset}{an optional vector specifying a subset of observations to be used.}
  \item{masspoints}{checks and controls for repeated observations in the running variable. Options are:

    (i)  \code{off}: ignores the presence of mass points; 

    (ii) \code{check}: looks for and reports the number of unique observations at each side of the cutoff. 

    (iii) \code{adjust}: controls that the preliminary bandwidths used in the calculations contain a minimal number of unique observations. By default it uses 10 observations, but it can be manually adjusted with the option \code{bwcheck}. 

    Default option is \code{masspoints=adjust}.}
    \item{bwcheck}{if a positive integer is provided, the preliminary bandwidth used in the calculations is enlarged so that at least \code{bwcheck} unique observations are used.}

    \item{bwrestrict}{if \code{TRUE}, computed bandwidths are restricted to lie within the range of \code{x}; default is \code{bwrestrict = TRUE}.}

    \item{stdvars}{if \code{TRUE}, \code{x} and \code{y} are standardized before computing the bandwidths; default is \code{stdvars = FALSE}.}
  \item{data}{an optional data frame. When supplied, \code{y}, \code{x}, \code{covs}, \code{cluster}, \code{fuzzy}, \code{weights}, and \code{subset} may be given as bare variable names referring to columns of \code{data}.}

\value{
  \item{N}{vector with the sample sizes used to the left and to the right of the cutoff.}
  \item{N_h}{vector with the effective sample sizes used to the left and to the right of the cutoff.}
  \item{N_b}{vector with the effective sample sizes used to the left and to the right of the cutoff for bias estimation.}
  \item{M}{vector with the number of unique observations to the left and to the right of the cutoff (when \code{masspoints} is not \code{off}).}
  \item{c}{cutoff value.}
  \item{p}{order of the polynomial used for estimation of the regression function.}
  \item{q}{order of the polynomial used for estimation of the bias of the regression function.}
  \item{bws}{matrix containing the bandwidths used: row \code{h} for the estimation bandwidth, row \code{b} for the bias bandwidth; columns \code{left} and \code{right}.}
  \item{tau_cl}{conventional local-polynomial estimate to the left and to the right of the cutoff.}
  \item{tau_bc}{bias-corrected local-polynomial estimate to the left and to the right of the cutoff.}
  \item{coef}{vector containing conventional and bias-corrected local-polynomial RD estimates.}
  \item{se}{vector containing conventional and robust standard errors of the local-polynomial RD estimates.}
  \item{bias}{estimated bias for the local-polynomial RD estimator below and above the cutoff.}
  \item{beta_Y_p_l}{conventional p-order local-polynomial estimates to the left of the cutoff for the outcome variable.}
  \item{beta_Y_p_r}{conventional p-order local-polynomial estimates to the right of the cutoff for the outcome variable.}
